/**
 * A JSON parser that mirrors CPython's `json.loads` semantics.
 *
 * Two things the built-in `JSON.parse` cannot give us and that the validator
 * needs in order to behave like the Python original:
 *
 *   1. `NaN` / `Infinity` / `-Infinity` literals are accepted (Python does).
 *   2. Whether a number literal was written as an integer (`3`) or as a float
 *      (`3.0`, `3e0`).  Python keeps `int` and `float` apart and `multipleOf`
 *      takes a different code path for each one.
 *
 * Parsed objects are created with a `null` prototype so that inherited keys
 * (`toString`, `constructor`, `__proto__`, ...) can never be confused with
 * real members, which is how Python dictionaries behave.
 */

export class JSONDecodeError extends Error {
  constructor(message, doc, pos) {
    const lineno = doc.slice(0, pos).split("\n").length;
    const colno = pos - doc.lastIndexOf("\n", pos - 1);
    super(`${message}: line ${lineno} column ${colno} (char ${pos})`);
    this.name = "JSONDecodeError";
    this.pos = pos;
  }
}

/** container -> set of member keys whose literal was a Python `float`. */
const FLOAT_MEMBERS = new WeakMap();

function markFloatMember(container, key) {
  let keys = FLOAT_MEMBERS.get(container);
  if (keys === undefined) {
    keys = new Set();
    FLOAT_MEMBERS.set(container, keys);
  }
  keys.add(String(key));
}

/** True when `container[key]` was written as a float literal in the source. */
export function isFloatMember(container, key) {
  if (container === null || typeof container !== "object") return false;
  const keys = FLOAT_MEMBERS.get(container);
  return keys !== undefined && keys.has(String(key));
}

const WHITESPACE = new Set([" ", "\t", "\n", "\r"]);

const ESCAPES = new Map([
  ['"', '"'],
  ["\\", "\\"],
  ["/", "/"],
  ["b", "\b"],
  ["f", "\f"],
  ["n", "\n"],
  ["r", "\r"],
  ["t", "\t"],
]);

const NUMBER_RE = /-?(?:0|[1-9][0-9]*)(\.[0-9]+)?([eE][-+]?[0-9]+)?/y;

class Decoder {
  constructor(text) {
    this.text = text;
    this.pos = 0;
    this.lastIsFloat = false;
  }

  fail(message, pos = this.pos) {
    throw new JSONDecodeError(message, this.text, pos);
  }

  skipWhitespace() {
    while (this.pos < this.text.length && WHITESPACE.has(this.text[this.pos])) {
      this.pos += 1;
    }
  }

  decode() {
    this.skipWhitespace();
    const value = this.parseValue();
    this.skipWhitespace();
    if (this.pos !== this.text.length) this.fail("Extra data");
    return value;
  }

  parseValue() {
    if (this.pos >= this.text.length) this.fail("Expecting value");
