/**
 * A very small stand-in for the slice of `argparse` used by the original
 * script: two required, string valued options (`--a` and `--b`) plus the
 * automatic `-h/--help`.
 *
 * Behaviours that are reproduced on purpose:
 *   - `--a VALUE` and `--a=VALUE` are both accepted,
 *   - the last occurrence of an option wins,
 *   - an argument that merely looks like a negative number is a value, not an
 *     option (the parser owns no numeric looking option strings),
 *   - `--` terminates option parsing,
 *   - usage/errors go to stderr and exit with status 2,
 *   - `-h`/`--help` prints the help text and exits with status 0.
 */

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  constructor({ prog, options }) {
    this.prog = prog;
    this.options = options;
  }

  usage() {
    const parts = this.options.map((opt) => `--${opt.name} ${opt.metavar}`);
    return `usage: ${this.prog} [-h] ${parts.join(" ")}`;
  }

  help() {
    const lines = [this.usage(), "", "options:", "  -h, --help  show this help message and exit"];
    for (const opt of this.options) {
      lines.push(`  --${opt.name} ${opt.metavar}       ${opt.help}`);
    }
    return lines.join("\n");
  }

  error(message) {
    process.stderr.write(`${this.usage()}\n`);
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  exitWithHelp() {
    process.stdout.write(`${this.help()}\n`);
    process.exit(0);
  }

  /** True when `token` should be treated as an option string. */
  looksLikeOption(token) {
    if (!token.startsWith("-")) return false;
    if (token === "-" || token === "--") return true;
    if (NEGATIVE_NUMBER.test(token)) return false;
    if (token.includes(" ")) return false;
    return true;
  }

  /** Resolve an option name, honouring argparse's unambiguous abbreviations. */
  resolve(name) {
    const exact = this.options.find((opt) => opt.name === name);
    if (exact !== undefined) return exact;
    const prefixed = this.options.filter((opt) => opt.name.startsWith(name));
    if (prefixed.length === 1) return prefixed[0];
    if (prefixed.length > 1) {
      const choices = prefixed.map((opt) => `--${opt.name}`).join(", ");
      this.error(`ambiguous option: --${name} could match ${choices}`);
    }
    return undefined;
  }

  parseArgs(argv) {
    const values = Object.create(null);
    const extras = [];
    let optionsFinished = false;

    for (let i = 0; i < argv.length; i += 1) {
      const token = argv[i];

      if (optionsFinished || !this.looksLikeOption(token)) {
        extras.push(token);
        continue;
      }
      if (token === "--") {
        optionsFinished = true;
        continue;
      }
      if (token === "-h" || token === "--help") {
        this.exitWithHelp();
      }
      if (!token.startsWith("--")) {
        extras.push(token);
        continue;
      }

      const body = token.slice(2);
      const eq = body.indexOf("=");
      const name = eq === -1 ? body : body.slice(0, eq);

      if (name === "help" || (name.length > 0 && "help".startsWith(name) && this.resolve(name) === undefined)) {
        this.exitWithHelp();
      }

      const option = this.resolve(name);
      if (option === undefined) {
        extras.push(token);
        continue;
      }
      if (eq !== -1) {
        values[option.name] = body.slice(eq + 1);
        continue;
      }
      const next = argv[i + 1];
      if (next === undefined || this.looksLikeOption(next)) {
        this.error(`argument --${option.name}: expected one argument`);
      }
      values[option.name] = next;
      i += 1;
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(" ")}`);
    }

    const missing = this.options
      .filter((opt) => opt.required && values[opt.name] === undefined)
      .map((opt) => `--${opt.name}`);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(", ")}`);
    }

    return values;
  }
}

