/**
 * Error objects and the error tree, mirroring `jsonschema.exceptions`.
 */

/** Sentinel standing in for Python's `_unset`. */
export const UNSET = Symbol("unset");

export class ValidationError extends Error {
  constructor(message, { validator = UNSET, validatorValue = UNSET, instance = UNSET, schema = UNSET, context = [], cause = null } = {}) {
    super(message);
    this.name = "ValidationError";
    this.message = message;
    this.validator = validator;
    this.validatorValue = validatorValue;
    this.instance = instance;
    this.schema = schema;
    this.context = context;
    this.cause = cause;
    /** Absolute path into the instance, built up while unwinding `descend`. */
    this.path = [];
    /** Absolute path into the schema. */
    this.schemaPath = [];
  }

  /** `ValidationError._set`: only fills in attributes that are still unset. */
  applyDefaults(attributes) {
    for (const [key, value] of Object.entries(attributes)) {
      if (this[key] === UNSET) this[key] = value;
    }
  }
}

export class SchemaError extends Error {
  constructor(message) {
    super(message);
    this.name = "SchemaError";
  }

  static createFrom(error) {
    const schemaError = new SchemaError(error.message);
    schemaError.validator = error.validator;
    schemaError.path = error.path;
    schemaError.schemaPath = error.schemaPath;
    return schemaError;
  }
}

/** Raised for a `type` keyword naming a type the checker does not know. */
export class UnknownType extends Error {
  constructor(type) {
    super(`Unknown type ${JSON.stringify(type)}`);
    this.name = "UnknownType";
  }
}

/** Raised when a `$ref` cannot be resolved (`_WrappedReferencingError`). */
export class ReferencingError extends Error {
  constructor(message) {
    super(message);
    this.name = "ReferencingError";
  }
}

/**
 * Python dict keys distinguish `0` from `"0"`, so path elements are tagged
 * with their kind before being used as map keys.
 */
function pathKey(element) {
  return typeof element === "number" ? `i:${element}` : `s:${element}`;
}

/** Keyword the error came from; `null` for "false schema" errors. */
function validatorKey(error) {
  const validator = error.validator;
  if (validator === UNSET || validator === null || validator === undefined) {
    return "�none";
  }
  return `k:${validator}`;
}

/**
 * `jsonschema.exceptions.ErrorTree`.
 *
 * Errors are filed under their instance path; within a node only one error is
 * kept per validation keyword, exactly like the Python dict assignment
 * `container.errors[error.validator] = error`.
 */
export class ErrorTree {
  constructor(errors = []) {
    this.errors = new Map();
    this._contents = new Map();

    for (const error of errors) {
      let container = this;
      for (const element of error.path) {
        const key = pathKey(element);
        let child = container._contents.get(key);
        if (child === undefined) {
          child = new ErrorTree();
          container._contents.set(key, child);
        }
        container = child;
      }
      container.errors.set(validatorKey(error), error);
      container._instance = error.instance;
    }
  }

  /** Number of errors in this node plus, recursively, all of its children. */
  get totalErrors() {
    let childErrors = 0;
    for (const child of this._contents.values()) {
      childErrors += child.totalErrors;
    }
    return this.errors.size + childErrors;
  }

  get length() {
    return this.totalErrors;
  }
}

