/**
 * Bridging Python's `re` module to JavaScript's `RegExp`.
 *
 * Two jobs:
 *   - decide whether a pattern is one `re.compile` would accept (the draft 7
 *     meta-schema declares `"format": "regex"` for `pattern`, and a bad
 *     pattern there is a schema error),
 *   - translate the Python-only spellings so that matching behaves the same.
 */

export class PythonRegexError extends Error {
  constructor(message) {
    super(message);
    this.name = "PythonRegexError";
  }
}

/**
 * Escapes `re` accepts after a backslash.  Any other ASCII letter is a
 * "bad escape" in Python even though JavaScript happily treats it as a
 * literal, so the two engines have to be told apart explicitly.
 */
const VALID_ESCAPE_LETTERS = new Set([
  "a", "b", "d", "f", "n", "r", "s", "t", "u", "v", "w", "x",
  "A", "B", "D", "N", "S", "U", "W", "Z",
]);

const ASCII_LETTER = /[A-Za-z]/;

const FLAG_TRANSLATION = new Map([
  ["i", "i"],
  ["m", "m"],
  ["s", "s"],
  ["a", ""],
  ["u", ""],
  ["L", ""],
  ["x", null], // verbose mode has no JavaScript equivalent
]);

/**
 * Rewrite a Python pattern into JavaScript source, raising for anything
 * `re.compile` would reject.
 */
function translate(pattern) {
  if (typeof pattern !== "string") {
    throw new PythonRegexError("pattern must be a string");
  }

  let out = "";
  let flags = "";
  let depth = 0;
  let inClass = false;
  let classStart = -1;
  let i = 0;

  while (i < pattern.length) {
    const char = pattern[i];

    if (char === "\\") {
      const next = pattern[i + 1];
      if (next === undefined) {
        throw new PythonRegexError("bad escape (end of pattern)");
      }
      if (ASCII_LETTER.test(next) && !VALID_ESCAPE_LETTERS.has(next)) {
        throw new PythonRegexError(`bad escape \\${next}`);
      }
      if (!inClass && next === "A") {
        out += "^";
      } else if (!inClass && next === "Z") {
        out += "$";
      } else {
        out += char + next;
      }
      i += 2;
      continue;
    }

    if (inClass) {
      if (char === "]" && i > classStart + 1) inClass = false;
      out += char;
      i += 1;
      continue;
    }

    if (char === "[") {
      inClass = true;
      classStart = i;
      // A leading "^]" or "]" is a literal closing bracket in both engines.
      if (pattern[i + 1] === "^") classStart += 1;
      out += char;
      i += 1;
      continue;
    }

    if (char === "]") {
      // Unmatched ] is a literal in Python but not in JavaScript's unicode
      // mode; escaping keeps both engines happy.
      out += "\\]";
      i += 1;
      continue;
    }

    if (char === "(") {
      depth += 1;
      if (pattern.startsWith("(?P<", i)) {
        const end = pattern.indexOf(">", i + 4);
        if (end === -1) throw new PythonRegexError("missing >, unterminated name");
        out += `(?<${pattern.slice(i + 4, end)}>`;
        i = end + 1;
        continue;
      }
      if (pattern.startsWith("(?P=", i)) {
        const end = pattern.indexOf(")", i + 4);
        if (end === -1) throw new PythonRegexError("missing ), unterminated name");
        out += `\\k<${pattern.slice(i + 4, end)}>`;
        depth -= 1;
        i = end + 1;
        continue;
      }
      if (pattern.startsWith("(?#", i)) {
        const end = pattern.indexOf(")", i + 3);
        if (end === -1) throw new PythonRegexError("missing ), unterminated comment");
        depth -= 1;
        i = end + 1;
        continue;
      }
      if (pattern.startsWith("(?<", i)) {
        const after = pattern[i + 3];
        if (after !== "=" && after !== "!") {
          throw new PythonRegexError(`unknown extension ?<${after ?? ""}`);
        }
        out += "(?<" + after;
        i += 4;
        continue;
      }
      if (pattern.startsWith("(?", i)) {
        const flagMatch = /^\(\?([aiLmsux]+)([):])/.exec(pattern.slice(i));
        if (flagMatch !== null) {
          for (const flag of flagMatch[1]) {
            const translated = FLAG_TRANSLATION.get(flag);
            if (translated === null) {
              throw new PythonRegexError(`unsupported inline flag (?${flag})`);
            }
            if (translated !== "" && !flags.includes(translated)) flags += translated;
          }
          if (flagMatch[2] === ")") {
            depth -= 1;
            i += flagMatch[0].length;
          } else {
            out += "(?:";
            i += flagMatch[0].length;
          }
          continue;
        }
      }
      out += char;
      i += 1;
      continue;
    }

    if (char === ")") {
      depth -= 1;
      if (depth < 0) throw new PythonRegexError("unbalanced parenthesis");
      out += char;
      i += 1;
      continue;
    }

    out += char;
    i += 1;
  }

  if (inClass) throw new PythonRegexError("unterminated character set");
  if (depth !== 0) throw new PythonRegexError("missing ), unterminated subpattern");

  return { source: out, flags };
}

/**
 * Compile `pattern` and return a predicate behaving like `re.search`.
 * Throws `PythonRegexError` for patterns Python would reject.
 */
export function compileSearch(pattern) {
  const { source, flags } = translate(pattern);
  let regex;
  try {
    // Unicode mode matches Python's code point view of the subject string.
    regex = new RegExp(source, `${flags}u`);
  } catch {
    try {
      regex = new RegExp(source, flags);
    } catch (error) {
      throw new PythonRegexError(error.message);
    }
  }
  return (text) => {
    regex.lastIndex = 0;
    return regex.test(text);
  };
}

/** Whether `re.compile(pattern)` would succeed. */
export function isValidRegex(pattern) {
  try {
    compileSearch(pattern);
    return true;
  } catch {
    return false;
  }
}

