import { ValidationError } from "./exceptions.mjs";
import { isFloatMember } from "../json/parser.mjs";
import { compileSearch } from "./regex.mjs";
import {
  codePointLength,
  equal,
  extrasMessage,
  findAdditionalProperties,
  objectSize,
  repr,
  uniq,
} from "./utils.mjs";
import { isObject } from "./types.mjs";

/** Python's `len()`; raises for values that have no length. */
