    for (const extra of extras) {
      yield* validator.descend(instance[extra], aP, { path: extra });
    }
  } else if (!aP && extras.length > 0) {
    if (Object.hasOwn(schema, "patternProperties")) {
      const verb = extras.length === 1 ? "does" : "do";
      const joined = [...extras].sort().map(repr).join(", ");
      const patterns = Object.keys(schema.patternProperties).sort().map(repr).join(", ");
      yield new ValidationError(`${joined} ${verb} not match any of the regexes: ${patterns}`);
