  if (!validator.isType(instance, "array")) return;
  if (validator.isType(itemsSchema, "array")) {
    const count = Math.min(instance.length, itemsSchema.length);
    for (let index = 0; index < count; index += 1) {
      yield* validator.descend(instance[index], itemsSchema[index], {
        path: index,
        schemaPath: index,
      });
    }
  } else {
    for (let index = 0; index < instance.length; index += 1) {
      yield* validator.descend(instance[index], itemsSchema, { path: index });
    }
  }
}

export function* additionalItems(validator, aI, instance, schema) {
  const declared = Object.hasOwn(schema, "items") ? schema.items : {};
  if (!validator.isType(instance, "array") || validator.isType(declared, "object")) return;

  const lenItems = pyLen(Object.hasOwn(schema, "items") ? schema.items : []);
  if (validator.isType(aI, "object")) {
    for (let index = lenItems; index < instance.length; index += 1) {
      yield* validator.descend(instance[index], aI, { path: index });
    }
