  if (!equal(instance, constValue)) {
    yield new ValidationError(`${repr(constValue)} was expected`);
  }
}

export function* contains(validator, containsSchema, instance) {
  if (!validator.isType(instance, "array")) return;
  const matched = instance.some((element) => validator.evolve(containsSchema).isValid(element));
  if (!matched) {
    yield new ValidationError(`None of ${repr(instance)} are valid under the given schema`);
  }
