  if (!validator.isType(instance, "number")) return;
  if (instance <= minimum) {
    yield new ValidationError(`${repr(instance)} is less than or equal to the minimum of ${repr(minimum)}`);
  }
}

export function* exclusiveMaximum(validator, maximum, instance) {
  if (!validator.isType(instance, "number")) return;
  if (instance >= maximum) {
    yield new ValidationError(`${repr(instance)} is greater than or equal to the maximum of ${repr(maximum)}`);
  }
}

export function* minimum(validator, minimumValue, instance) {
  if (!validator.isType(instance, "number")) return;
  comparable(instance, minimumValue);
  if (instance < minimumValue) {
