  if (!validator.isType(instance, "object")) return;
  for (const property of Object.keys(deps)) {
    if (!Object.hasOwn(instance, property)) continue;
    const dependency = deps[property];
    if (validator.isType(dependency, "array")) {
      for (const each of dependency) {
        if (!Object.hasOwn(instance, each)) {
