        path: property,
        schemaPath: property,
      });
    }
  }
}

export function* required(validator, requiredProps, instance) {
  if (!validator.isType(instance, "object")) return;
  for (const property of requiredProps) {
    if (!Object.hasOwn(instance, property)) {
      yield new ValidationError(`${repr(property)} is a required property`);
    }
  }
}

export function* minProperties(validator, count, instance) {
  if (validator.isType(instance, "object") && objectSize(instance) < count) {
    yield new ValidationError(`${repr(instance)} does not have enough properties`);
  }
}

export function* maxProperties(validator, count, instance) {
  if (!validator.isType(instance, "object")) return;
  if (objectSize(instance) > count) {
    yield new ValidationError(`${repr(instance)} has too many properties`);
  }
}

