 * package that `jsonschema` leans on for draft 7.
 */

import { ReferencingError } from "./exceptions.mjs";
import { isObject } from "./types.mjs";

const URI_RE = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/;

function splitUri(uri) {
  const match = URI_RE.exec(uri);
  return {
    scheme: match[1],
    authority: match[2],
    path: match[3] ?? "",
    query: match[4],
    fragment: match[5],
  };
}

function removeDotSegments(path) {
  const out = [];
  for (const segment of path.split("/")) {
    if (segment === ".") continue;
    if (segment === "..") {
      out.pop();
      continue;
    }
    out.push(segment);
  }
  let joined = out.join("/");
  if (/(^|\/)(\.|\.\.)$/.test(path) && !joined.endsWith("/")) joined += "/";
  return joined;
}

function unsplitUri({ scheme, authority, path, query, fragment }) {
  let out = "";
  if (scheme !== undefined) out += `${scheme}:`;
  if (authority !== undefined) out += `//${authority}`;
  out += path;
  if (query !== undefined) out += `?${query}`;
  if (fragment !== undefined) out += `#${fragment}`;
  return out;
}

/** RFC 3986 reference resolution, the behaviour of `urllib.parse.urljoin`. */
export function urljoin(base, reference) {
  if (base === "") return reference;
  if (reference === "") return unsplitUri({ ...splitUri(base), fragment: undefined });

  const ref = splitUri(reference);
  const target = splitUri(base);

  if (ref.scheme !== undefined && ref.scheme !== target.scheme) return reference;

  if (ref.authority !== undefined) {
    return unsplitUri({
      scheme: target.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
      fragment: ref.fragment,
    });
  }

  let path;
  if (ref.path === "") {
    path = target.path;
  } else if (ref.path.startsWith("/")) {
    path = removeDotSegments(ref.path);
  } else {
    const merged = target.path.slice(0, target.path.lastIndexOf("/") + 1) + ref.path;
    path = removeDotSegments(target.authority !== undefined && target.path === "" ? `/${ref.path}` : merged);
  }

  return unsplitUri({
    scheme: target.scheme,
    authority: target.authority,
    path,
    query: ref.path === "" && ref.query === undefined ? target.query : ref.query,
    fragment: ref.fragment,
  });
