  /** Register `contents` under `uri` and index everything nested inside it. */
  withResource(uri, contents) {
    this.resources.set(uri, contents);
    this.crawl(contents, uri);
    return this;
  }

  crawl(contents, baseUri) {
    if (!isObject(contents)) return;
    for (const subresource of subresourcesOf(contents)) {
      if (!isObject(subresource)) continue;
