      const anchor = anchorOf(subresource);
      if (anchor !== null) {
        this.anchors.set(`${baseUri}${ANCHOR_SEPARATOR}${anchor}`, subresource);
      }
      this.crawl(subresource, base);
    }
  }

  getResource(uri) {
    if (this.resources.has(uri)) return this.resources.get(uri);
    if (this.parent !== null) return this.parent.getResource(uri);
    return undefined;
  }

  getAnchor(baseUri, name) {
    const key = `${baseUri}${ANCHOR_SEPARATOR}${name}`;
    if (this.anchors.has(key)) return this.anchors.get(key);
    if (this.parent !== null) return this.parent.getAnchor(baseUri, name);
    return undefined;
  }

