  constructor(registry, baseUri) {
    this.registry = registry;
    this.baseUri = baseUri;
  }

  /** `Resolver.in_subresource`: follow a nested `$id` scope. */
  inSubresource(contents) {
    const id = idOf(contents);
    if (id === null) return this;
    return new Resolver(this.registry, urljoin(this.baseUri, id));
  }

  /** Resolve `ref`, returning its contents and the resolver to continue with. */
  lookup(ref) {
    if (typeof ref !== "string") {
      throw new ReferencingError(`Unresolvable: ${String(ref)}`);
    }

    let uri;
    let fragment;
    if (ref.startsWith("#")) {
      uri = this.baseUri;
      fragment = ref.slice(1);
    } else {
      const joined = urljoin(this.baseUri, ref);
      const hash = joined.indexOf("#");
      uri = hash === -1 ? joined : joined.slice(0, hash);
      fragment = hash === -1 ? "" : joined.slice(hash + 1);
    }

    const resource = this.registry.getResource(uri);
    if (resource === undefined) throw new ReferencingError(`Unresolvable: ${ref}`);

    if (fragment.startsWith("/")) {
      return this.followPointer(resource, uri, fragment, ref);
    }
    if (fragment !== "") {
      const anchored = this.registry.getAnchor(uri, decode(fragment));
      if (anchored === undefined) throw new ReferencingError(`Unresolvable: ${ref}`);
      return {
        contents: anchored,
        resolver: new Resolver(this.registry, uri).inSubresource(anchored),
      };
    }
    return { contents: resource, resolver: new Resolver(this.registry, uri) };
  }

  followPointer(resource, uri, pointer, ref) {
    let contents = resource;
    let resolver = new Resolver(this.registry, uri);

    for (const raw of decode(pointer).slice(1).split("/")) {
      const segment = raw.replace(/~1/g, "/").replace(/~0/g, "~");
      if (Array.isArray(contents)) {
        const index = Number(segment);
        if (!Number.isInteger(index) || index < 0 || index >= contents.length) {
          throw new ReferencingError(`PointerToNowhere: '${pointer}' does not exist`);
        }
        contents = contents[index];
      } else if (isObject(contents) && Object.hasOwn(contents, segment)) {
        contents = contents[segment];
      } else {
        throw new ReferencingError(`PointerToNowhere: '${pointer}' does not exist`);
      }
      if (isObject(contents) || typeof contents === "boolean") {
        resolver = resolver.inSubresource(contents);
      }
    }
    void ref;
    return { contents, resolver };
  }
}

function decode(text) {
  try {
    return decodeURIComponent(text);
  } catch {
    return text;
  }
}

