  resolverWithRoot(contents) {
    const uri = idOf(contents) ?? "";
    this.withResource(uri, contents);
    return new Resolver(this, uri);
  }
}

export class Resolver {
  constructor(registry, baseUri) {
    this.registry = registry;
    this.baseUri = baseUri;
  }

  /** `Resolver.in_subresource`: follow a nested `$id` scope. */
  inSubresource(contents) {
    const id = idOf(contents);
    if (id === null) return this;
    return new Resolver(this.registry, urljoin(this.baseUri, id));
  }

  /** Resolve `ref`, returning its contents and the resolver to continue with. */
  lookup(ref) {
    if (typeof ref !== "string") {
      throw new ReferencingError(`Unresolvable: ${String(ref)}`);
    }

    let uri;
    let fragment;
    if (ref.startsWith("#")) {
      uri = this.baseUri;
      fragment = ref.slice(1);
    } else {
      const joined = urljoin(this.baseUri, ref);
      const hash = joined.indexOf("#");
      uri = hash === -1 ? joined : joined.slice(0, hash);
      fragment = hash === -1 ? "" : joined.slice(hash + 1);
    }

    const resource = this.registry.getResource(uri);
    if (resource === undefined) throw new ReferencingError(`Unresolvable: ${ref}`);

    if (fragment.startsWith("/")) {
      return this.followPointer(resource, uri, fragment, ref);
    }
    if (fragment !== "") {
      const anchored = this.registry.getAnchor(uri, decode(fragment));
      if (anchored === undefined) throw new ReferencingError(`Unresolvable: ${ref}`);
