        contents: anchored,
        resolver: new Resolver(this.registry, uri).inSubresource(anchored),
      };
    }
    return { contents: resource, resolver: new Resolver(this.registry, uri) };
  }

  followPointer(resource, uri, pointer, ref) {
    let contents = resource;
    let resolver = new Resolver(this.registry, uri);

    for (const raw of decode(pointer).slice(1).split("/")) {
      const segment = raw.replace(/~1/g, "/").replace(/~0/g, "~");
      if (Array.isArray(contents)) {
        const index = Number(segment);
        if (!Number.isInteger(index) || index < 0 || index >= contents.length) {
          throw new ReferencingError(`PointerToNowhere: '${pointer}' does not exist`);
        }
        contents = contents[index];
      } else if (isObject(contents) && Object.hasOwn(contents, segment)) {
        contents = contents[segment];
      } else {
        throw new ReferencingError(`PointerToNowhere: '${pointer}' does not exist`);
      }
      if (isObject(contents) || typeof contents === "boolean") {
        resolver = resolver.inSubresource(contents);
      }
    }
    void ref;
    return { contents, resolver };
  }
}

function decode(text) {
  try {
    return decodeURIComponent(text);
  } catch {
    return text;
  }
}

