   * `Draft7Validator.check_schema`: validate a schema against the draft 7
   * meta-schema (with format checking on) and raise on the first error.
   * Returns `None`, like the Python classmethod.
   */
  static checkSchema(schema) {
    const validator = new Draft7Validator(Draft7Validator.META_SCHEMA, {
      formatChecker: Draft7Validator.FORMAT_CHECKER,
    });
    for (const error of validator.iterErrors(schema)) {
      throw SchemaError.createFrom(error);
    }
    return null;
  }
}

function falseSchemaError(instance, schema) {
  return new ValidationError(`False schema does not allow ${repr(instance)}`, {
    validator: null,
    validatorValue: null,
    instance,
    schema,
  });
}

/** Run every applicable keyword of `schema` over `instance`. */
function* runKeywords(validator, instance, schema) {
  for (const [keyword, value] of applicableValidators(schema)) {
    const keywordValidator = Draft7Validator.VALIDATORS.get(keyword);
    if (keywordValidator === undefined) continue;

    for (const error of keywordValidator(validator, value, instance, schema)) {
      error.applyDefaults({
        validator: keyword,
        validatorValue: value,
        instance,
        schema,
      });
      if (keyword !== "if" && keyword !== "$ref") error.schemaPath.unshift(keyword);
      yield error;
    }
  }
}

