/**
 * Port of dataset/jsonschema/test18.py.
 *
 * Builds a Draft 7 validator, collects the validation errors for an instance,
 * groups them into an error tree, and re-runs the same checks a few times to
 * show the results are stable.
 */

import { basename } from "node:path";

import { ArgumentParser } from "./lib/cli/argparse.mjs";
import { loads } from "./lib/json/parser.mjs";
import { Draft7Validator, ErrorTree } from "./lib/jsonschema/index.mjs";

/** `print()` for the handful of Python types this script outputs. */
function print(value) {
  if (value === null || value === undefined) {
    process.stdout.write("None\n");
  } else if (value === true) {
    process.stdout.write("True\n");
  } else if (value === false) {
    process.stdout.write("False\n");
  } else {
    process.stdout.write(`${value}\n`);
  }
}

const parser = new ArgumentParser({
  prog: basename(process.argv[1] ?? "test18.mjs"),
  options: [
    { name: "a", metavar: "A", required: true, help: "instance (JSON string)" },
    { name: "b", metavar: "B", required: true, help: "schema (JSON string)" },
  ],
});
const args = parser.parseArgs(process.argv.slice(2));

const instance = loads(args.a);
const schema = loads(args.b);

const validator = new Draft7Validator(schema);

// Build error tree
