#!/usr/bin/env node
/* Differential harness: runs every case through the Python executable and the
   Node port, comparing stdout and exit status. */
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";

const PY = "/workspace/dataset/test18_executable";
const JS = "/output/test18.mjs";

function run(cmd, args) {
  try {
    const stdout = execFileSync(cmd, args, { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
    return { code: 0, stdout };
  } catch (error) {
    return { code: error.status === null ? -1 : error.status, stdout: error.stdout ?? "" };
  }
}

const cases = JSON.parse(readFileSync(process.argv[2], "utf8"));
let failures = 0;
for (const [a, b] of cases) {
  const py = run(PY, ["--a", a, "--b", b]);
  const js = run("node", [JS, "--a", a, "--b", b]);
  const pyOk = py.code === 0;
  const jsOk = js.code === 0;
  const same = pyOk === jsOk && (pyOk ? py.stdout === js.stdout : true);
  if (!same) {
    failures += 1;
    console.log(`FAIL a=${a}\n     b=${b}`);
    console.log(`  py(${py.code}): ${JSON.stringify(py.stdout)}`);
    console.log(`  js(${js.code}): ${JSON.stringify(js.stdout)}`);
  }
}
console.log(`${cases.length - failures}/${cases.length} matched`);
process.exit(failures === 0 ? 0 : 1);

